"""Generate fallback inventory and pending measurement tables from retained evidence."""
import json
from pathlib import Path
OUT=Path(__file__).resolve().parents[1]
rows=json.loads((OUT/'screen-manifest.json').read_text())
captures=json.loads((OUT/'capture-manifest.json').read_text())
http={r['name']:r for r in json.loads((OUT/'http-observations.json').read_text())}
def write(name,text):(OUT/name).write_text(text+'\n')
issue_map={
 'questionnaire':'UI-001, UI-002, UI-004, UI-008', 'nist-questionnaire':'UI-001, UI-002, UI-004', 'conclusions':'UI-006, UI-009', 'interim-conclusions':'UI-006, UI-009','review-queue':'UI-003, UI-006, UI-008', 'report':'UI-007, UI-008', 'report-iso':'UI-007, UI-008', 'report-summary':'UI-007', 'report-summary-iso':'UI-007','rfi-items':'UI-005, UI-009','rfi-versions':'UI-008, UI-009','rfi-links':'UI-008, UI-009','requests':'UI-005, UI-009', 'scope':'UI-002, UI-008','workpaper':'UI-002, UI-006','evidence-global':'UI-001, UI-009','evidence-engagement':'UI-001, UI-009','evidence-assessment':'UI-001, UI-009'}
components={'questionnaire':'Section navigation, question cards, answer groups, notes disclosure, citations, section save','review-queue':'Queue navigation, outcome dots, decision editor, evidence quotes, shortcuts','conclusions':'Filter pills, expandable table, conclusion editor, citation cards','rfi-items':'Request checklist, guidance blocks, mapped-control disclosure','requests':'Assessment request table, client links, create-link form','report':'Framework picker, report tabs, async report summary','report-summary':'Score and coverage, findings table, domain disclosure, release basis','evidence-assessment':'Inventory table, filters, upload and version actions','evidence-record':'Version state, document text, extracted workbook tables','settings':'Brand and accent controls, firm configuration form','aws-evidence':'Connection configuration, policy code blocks, pull state','purge':'Retention status, destructive confirmation','comparison':'Period comparison, framework scores, matched-control table'}
lines=['# Screen inventory','', 'This is an A2 fallback inventory, based on route responses and source. No screenshots were produced and no visual severity was assigned from appearance. All listed filenames are requested captures, not existing evidence. The 31 page-template figure expands to 38 required live route variants when scope/tab variants are separated. Supplemental live states, all 44 registered fixture names and read-only interaction captures are listed as well.', '', 'Information density is a task/content classification, not a measured visual judgment. HTTP text includes hidden markup and does not prove what is visible. Each task is the primary decision; the secondary task is inspecting provenance, history or supporting detail. Screens with no unique issue still inherit shared shell and accessibility checks.', '', '## Required live route coverage','', '| Screen | Route | Primary task | Secondary task | Density | Major components | Source/HTML issue candidates; severity | HTTP | Requested 1440 / 1280 |','|---|---|---|---|---|---|---|---|---|']
def rowline(r):
 name=r['name']; h=http.get(name,{}); ids=issue_map.get(name,'UI-008, UI-010 (shared shell)')
 if r['group']=='fixture':
  ids='State appearance and interaction pending'
  if name.startswith('b6-magic_upload'):ids='HTTP 500; upload fixture unavailable; UI-011 source risk'
  if name.startswith('b6-comparison'):ids='HTTP 404; fixture hardcodes absent prior id'
 if r['group']=='interaction':ids='Interaction unverified; requested read-only state'
 severity='High candidate' if any(i in ids for i in ('UI-001','UI-002','UI-003','UI-004','UI-006','UI-007','UI-011')) else 'Medium candidate' if 'UI-' in ids else 'Not visually rated'
 return f'| {name} | `{r["path"]}` | {r["task"]} | Inspect supporting detail and history | {r["density"]} | {components.get(name,r["components"])} | {ids}; {severity} | {h.get("status","Not requested separately")} | `{name}-1440.png` / `{name}-1280.png` |'
lines += [rowline(r) for r in rows if r['group']=='live']
for group,title in [('additional-live','Supplemental live states'),('fixture','No-spend fixtures'),('interaction','Expanded, selected, edit and citation states'),('gallery','Component gallery')]:
 lines+=['',f'## {title}','','| Screen/state | Route | Primary task | Secondary task | Density | Major components | Observations and severity | HTTP | Requested 1440 / 1280 |','|---|---|---|---|---|---|---|---|---|']
 lines += [rowline(r) for r in rows if r['group']==group]
lines += ['', '## Theme and mobile coverage', '', 'Five dark-theme captures are requested at 1440: requests, assessment evidence inventory, questionnaire, review queue and report. Upload default, uploading, done and error states each have a 390px request. All other captures use light at 1440 and 1280. Every capture is enumerated with its interaction in [CAPTURE_REQUESTS.md](CAPTURE_REQUESTS.md).', '', '## HTTP findings and cautions', '', 'All 38 required live variants returned 200 after redirects. `/review-queue` for the interim assessment is a real populated queue. Questionnaire fragments were retrieved separately because curl does not run HTMX. The current questionnaire contains 38 answered questions in seven sections; NIST has partly answered content. These source counts do not measure rendered text nodes.', '', 'Four upload fixture states return 500: `design_s8_client._active_link` requires the missing `s8-client-active` link. The comparison fixture returns 404: it hardcodes `assessment-s8-previous`, while the live comparison with the handoff prior id works. No seed or database changes were made. Fixture labels such as locked or shared do not guarantee the seeded data actually reproduces that state; confirm content before accepting a capture.', '', 'The default report selects DPDPA in this multi-framework demo. The supplemental ISO report and summary are included to inspect the 93-control body. The current released assessment also includes six legacy DPDPA conclusions, so mixed wording must be judged against the actual scope. This is not evidence of a blended score.', '', 'See [http-observations.json](http-observations.json) for exact status, effective URL, tags, text, links, forms and HTMX GET targets. Extracted text normalizes source long dashes to plain hyphens. Hidden rows and script-free states are not treated as visual observations.']
write('SCREEN_INVENTORY.md','\n'.join(lines))
lines=['# Deferred capture requests','', 'A2 fallback is active. The existing screenshot harness could not launch Chromium in this sandbox. Its stderr reports `bootstrap_check_in org.chromium.Chromium.MachPortRendezvousServer: Permission denied (1100)` followed by `TargetClosedError`. Port 8011 is reachable by curl. No browser restrictions were bypassed and no second server was started.', '', f'Requested: {len(captures)} full-page captures across {len(rows)} route/state/interaction entries. Captured: 0. The screenshots directory intentionally has no fabricated images. Width/type/line-length measurements are also deferred. Capture at device scale 1, height 1000; wait for fonts and HTMX load completion. Keep screenshot storage under about 60 MB; use JPEG quality 85 above 6000px and update the manifest filename if converted.', '', '## Execution', '', 'For default states use the existing harness, for example:', '', '```sh', '.venv/bin/python design/harness/screenshot.py "http://127.0.0.1:8011/" --width 1440 --height 1000 --full-page --output docs/ui-audit/screenshots/home-1440.png', '```', '', 'The retained [capture_measure.py](tools/capture_measure.py) uses the harness URL/theme helpers, blocks non-GET requests, captures interaction states and measures actual DOM geometry. Run it only on a host allowed to launch Chromium. It can filter by name with `--only questionnaire`. Its unresolved live confirmation interaction is deliberately reported as an error rather than submitting. Use the modal fixture to inspect confirmation anatomy. Check HTTP/content before accepting screenshots, since fixture upload currently fails and some fixtures rely on different seed data. Do not reseed or create links as part of this audit.', '', 'Fixes required outside this docs-only dispatch: provide the expected upload fixture seed without altering live data, and choose a valid comparison fixture assessment. The real comparison URL already works. The evidence-reuse preview requires `assessment=` rather than only `assessment_id=`; the requests below include both.', '', '## Capture rows', '', '| URL | Viewport | Theme | Interaction | Expected file |','|---|---|---|---|---|']
for c in captures: lines.append(f'| `http://127.0.0.1:8011{c["path"]}` | {c["width"]} x {c["height"]} | {c["theme"]} | {c["interaction"]} | `{c["filename"]}` |')
write('CAPTURE_REQUESTS.md','\n'.join(lines))
lines=['# Measurements and verification limits','', 'Browser measurements are unavailable because Chromium was blocked. No width, unused space, line length or rendered font-size count below is inferred from CSS. Source constraints are discussed separately in ARCHITECTURE.md. This distinction is required by A5.', '', '## Per-screen desktop measurements', '', 'N/A means not measured. The text-node count column must become a size-to-count map for both widths, restricted to visible text in main content. The longest body block is selected from paragraphs/quotes/list items, its total character count retained, and its actual maximum rendered characters per line measured using Range rectangles. Unused width is viewport minus sidebar minus the main border box, including outer gutters; internal pane waste must be considered separately.', '', '| Screen/state | Content px 1440 / 1280 | Unused px 1440 / 1280 | Longest body block characters and line length 1440 / 1280 | Visible text nodes by font size 1440 / 1280 | Below-14px audit content |','|---|---|---|---|---|---|']
for r in rows:lines.append(f'| {r["name"]} | N/A / N/A | N/A / N/A | N/A / N/A | N/A / N/A | Pending DOM check |')
lines += ['', '## Static type risks, not rendered counts', '', '`yozora-components.css` makes `.help` 12px. `partials/section_questions.html` applies it to question guidance, skip reasons, confidence and desk-review notes. That violates the project reason-role target of 14px independently of whether contrast passes. Citation quotes inherit body type and `.concl` is 16px, so the report does not claim that all audit content is tiny. At capture time classify each below-14 node as metadata or decision-bearing content, using the text samples and selector in rendered-measurements.json.', '', '## Contrast method and complete matrix', '', 'The complete [contrast appendix](CONTRAST_APPENDIX.md) contains every source-discovered foreground-token candidate against declared surface families in light and dark, with each accent where needed. It is a conservative superset, not a list of verified DOM pairings. [contrast-data.json](contrast-data.json) retains declaration locations and all ratios; [contrast.py](tools/contrast.py) reproduces them. Source-computed values are rounded to three decimals. WCAG normal text requires 4.5:1; large text and non-text markers can use 3:1 when the applicable conditions hold.', '', 'The calculation linearizes sRGB channels, uses relative luminance and `(Llighter + .05)/(Ldarker + .05)`, samples 101 positions on each gradient segment, then composites declared alpha surfaces. Glass includes the CSS saturation approximation on a flat canvas. The min/max ratios cover lightest and darkest gradient contributions and intermediate samples. Nested surfaces are enumerated in the appendix. Blur, content behind overlays, custom firm colors, hover oklab mixing and disabled opacity are not certified. Print reports have a separate palette and are outside this portal audit.', '', 'The Playwright measurement tool also records computed foreground and ancestor background/opacity/image layers. Associate these with source tokens before calling a candidate failure an actual usage failure. Validate glass bounds by inspecting real backdrop pixels in the capture follow-up.', '', '### Base body tokens against canvas and reading surfaces', '', '| Theme | Text token | Surface | Minimum | Maximum | AA normal |','|---|---|---|---:|---:|---|']
data=json.loads((OUT/'contrast-data.json').read_text())
for r in data['rows']:
 if r['accent']=='all' and r['text'] in ('text','text-2','muted') and r['surface'] in ('canvas','glass','solid'):
  lines.append(f'| {r["theme"]} | {r["text"]} | {r["surface"]} | {r["min"]:.3f} | {r["max"]:.3f} | {"Pass" if r["aa_normal"] else "Fail candidate"} |')
lines += ['', '### Interpretation', '', 'Base text, secondary and muted tokens pass AA normal against the modeled canvas, glass and solid surfaces. Preserve this evidence when deciding whether a reading problem is size, hierarchy, repetition or contrast. Seven non-graphite presets retain light accent-text in dark theme and need pair-specific correction. Some primary gradient endpoint pairings fall below 4.5:1, but endpoint bounds are not proof that the text sits over that endpoint. Semantic amber/orange marker colors must not be used indiscriminately as small text.', '', 'The status inventory records where color is a fill, marker or foreground: [STATUS_INVENTORY.md](STATUS_INVENTORY.md). A badge can use a readable text token with a low-contrast colored marker without failing text contrast; inspect its actual anatomy.', '', '## Required follow-up', '', 'Run the retained capture/measurement tool on the already running app from an unrestricted browser host. Review screenshots by eye, check keyboard focus/history, resolve seed-dependent fixtures, replace pending geometry tables and associate every issue with an existing capture. This dispatch stops after source/HTTP Phase 12 under A2; it does not claim visual sign-off.']
write('MEASUREMENTS.md','\n'.join(lines))
lines=['# Complete source contrast appendix','', data['method'], '', 'Every row is source-computed. Candidate pairings may never occur in the DOM. Source declarations and limitations are retained in contrast-data.json. Token candidates include fallback variables discovered inside color declarations; canvas-mid is also used as the tooltip foreground (components.css:379), despite its name.', '', '| Theme | Accent | Foreground candidate | Surface | Min ratio | Max ratio | Worst background | Best background | AA normal | Pairing scope |','|---|---|---|---|---:|---:|---|---|---|---|']
for r in data['rows']:lines.append(f'| {r["theme"]} | {r["accent"]} | {r["text"]} | {r["surface"]} | {r["min"]:.3f} | {r["max"]:.3f} | {r["worst_background"]} | {r["best_background"]} | {"Pass" if r["aa_normal"] else "Fail candidate"} | {r["scope"]} |')
write('CONTRAST_APPENDIX.md','\n'.join(lines))
print('Wrote inventory, capture requests, measurements and contrast appendix')
